add("permissions_title","İzinler","Permissions"); add("permissions_sub","Arka planda güvenilir kayıt için dört adım. Hepsi isteğe bağlıdır ama sırayla verilmesi önerilir.","Four steps for reliable background recording. Each is optional but best done in order.")
add("perm_fine_title","Hassas konum","Precise location"); add("perm_fine_body","Uçuş kaydı ve retrieve için GPS konumun gerekir. 'Yaklaşık' yerine 'Hassas' seç.","GPS position is needed for recording and retrieves. Choose 'Precise', not 'Approximate'.")
add("perm_coarse_only","Yalnızca yaklaşık konum verilmiş. Hassas konuma izin ver.","Only approximate location is granted. Allow precise location.")
add("perm_allow","İzin ver","Allow")
add("perm_bg_title","Arka planda konum ('Her zaman')","Background location ('All the time')"); add("perm_bg_body","Ekran kilitliyken veya başka uygulamadayken kaydın sürmesi için gerekir.","Needed so recording continues with the screen locked or another app open.")
add("perm_bg_honest","Android bunu uygulama içinde değil, sistem ayarları ekranında sorar: 'Her zaman izin ver'i seç. Bu izin yalnızca sen bir uçuş kaydı başlattığında, retrieve beklerken veya retriever görevindeyken kullanılır.","Android asks for this on a system settings screen, not in the app: choose 'Allow all the time'. It is only used while you record a flight, wait for a retrieve or are on retriever duty.")
add("perm_bg_open","Her zaman iznini iste","Ask for 'all the time'")
add("perm_notif_title","Bildirimler","Notifications"); add("perm_notif_body","Kayıt bildirimi ve 'İndin mi?' hatırlatması için. Reddedersen kayıt yine çalışır ama bildirimi göremezsin.","For the recording notification and the 'Did you land?' reminder. If denied, recording still works but you will not see the notification.")
add("perm_battery_title","Pil optimizasyonu","Battery optimisation"); add("perm_battery_body","Pil optimizasyonundan muaf tutmak, Android'in kaydı uykuya almasını azaltır. Zorunlu değildir.","Exempting Retfast reduces the chance Android puts recording to sleep. Not mandatory.")
add("perm_battery_ask","Muafiyet iste","Ask for exemption"); add("perm_battery_oem","Bazı üreticilerde ayrıca 'Otomatik başlatma' veya 'Arka planda çalışmaya izin ver' ayarını açmak gerekir (Ayarlar > Pil / Uygulamalar).","On some manufacturers you must also enable 'Autostart' or 'Allow background activity' (Settings > Battery / Apps).")
